  ('ancient-olympia', 'Ancient Olympia', 'Αρχαία Ολυμπία', 'culture', 'Olympia', 63, 48, 37.6441431, 21.6252773, 7, 'historic but still iconic', 'medium', '€€', 'late afternoon', array['culture', 'unesco', 'walk', 'history']::text[], 'Ancient ruins, golden light, and a surprisingly good late-afternoon wander.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20archaeological%20site%20of%20Ancient%20Olympia%2C%20Greece%20%2851223832734%29.jpg?width=1200', 7, 6, 5, 'popular', 0),
