  ('korakochori', 'Korakochori', 'Κορακοχώρι', 'village', 'Pyrgos Coast', 27, 50, 37.6751019, 21.3144272, 4, 'coastal village between Katakolo and Pyrgos', 'low', '€', 'late afternoon', array['village', 'coast', 'quiet', 'wine']::text[], 'Small coastal village stop that anchors the Katakolo-to-Skafidia stretch.', 'https://visitkatakolon.gr/wp-content/uploads/2015/03/mercury.jpg', 4, 5, 2, 'active', 47),
  ('mercouri-estate', 'Mercouri Estate', 'Κτήμα Μερκούρη', 'food', 'Korakochori', 27, 50, 37.676717759856, 21.310256847083, 6, 'historic winery by the Katakolo coast', 'medium', '€€', 'morning tour', array['wine', 'estate', 'katakolo', 'food']::text[], 'Historic winery and estate near Korakochori, useful for a Katakolo/Olympia day that is not only ruins.', 'https://visitkatakolon.gr/wp-content/uploads/2015/03/Mercouri-Estate.jpeg', 6, 5, 4, 'active', 48),
  ('lechaina-zacharo-flower', 'Wild Coastline', 'Άγρια Ακτογραμμή', 'nature', 'Ilia Coast', 20, 62, 37.63, 21.315, 5, 'raw beach nature', 'low', 'free', 'morning', array['wild', 'coast', 'nature', 'quiet']::text[], 'A raw coastal stretch for quiet walks, salt air, and finding your own spot.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pancratium%20Maritimum%20Lechaina-Zaharo%20beach%2020140816.jpg?width=1200', 5, 5, 3, 'active', 49),
  ('epitalio', 'Epitalio', 'Επιτάλιο', 'village', 'Alfeios Plain', 46, 57, 37.6270957, 21.4959889, 4, 'plain village near the Alfeios route', 'low', '€', 'evening', array['village', 'alfeios', 'local', 'route']::text[], 'A real local point south of Pyrgos that helps connect the city to the Zacharo side.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Elis%20acropolis.JPG?width=1200', 4, 5, 2, 'active', 50)
