insert into public.posts (id, author_id, place_id, kind, display_time, text, tags, likes_count, image_url, sort_order)
values
  ('post-1', 'nikos', 'kourouta-beach', 'spot', '18 min ago', 'Kourouta is filling up already. Music starts after sunset. Don''t come too late if you want parking.', array['beach', 'tonight', 'parking']::text[], 48, 'https://commons.wikimedia.org/wiki/Special:FilePath/%CE%9A%CE%BF%CF%85%CF%81%CE%BF%CF%8D%CF%84%CE%B1%20-%20panoramio%20%281%29.jpg?width=1200', 0),
  ('post-2', 'maria', 'zacharo-beach', 'photo', '32 min ago', 'Zacharo sunset is insane and way less packed than expected.', array['sunset', 'quiet', 'cheap']::text[], 31, 'https://commons.wikimedia.org/wiki/Special:FilePath/500px%20photo%20%28255278229%29.jpeg?width=1200', 1),
  ('post-3', 'nikos', 'amaliada-square', 'tip', '1h ago', 'Pregame in Amaliada then Kourouta. Classic summer move.', array['pregame', 'local', 'after']::text[], 64, 'https://commons.wikimedia.org/wiki/Special:FilePath/%CE%A0%CE%BB%CE%B1%CF%84%CE%B5%CE%AF%CE%B1%20%CE%91%CE%BC%CE%B1%CE%BB%CE%B9%CE%AC%CE%B4%CE%B1.jpg?width=1200', 2),
  ('post-4', 'eleni', 'pyrgos-night', 'event', 'tonight', 'Small DJ thing near the old Rex corner. Starts late, obviously.', array['dj', 'night', 'local']::text[], 22, 'https://commons.wikimedia.org/wiki/Special:FilePath/%CE%9A%CE%B9%CE%BD%CE%B7%CE%BC%CE%B1%CF%84%CE%BF%CE%B3%CF%81%CE%AC%CF%86%CE%BF%CF%82%20%C2%AB%CE%A1%CE%AD%CE%BE%C2%BB.jpg?width=1200', 3),
  ('post-5', 'nikos', 'foloi-forest', 'tip', 'today', 'Foloi is perfect right now. Shade, quiet, no beach chaos. Bring water and don''t leave trash.', array['nature', 'respect', 'walk']::text[], 57, 'https://commons.wikimedia.org/wiki/Special:FilePath/Foloi%20Forest%20-%20panoramio.jpg?width=1200', 4),
  ('post-6', 'andreas', 'agios-andreas', 'spot', '2h ago', 'Fresh fish tonight, tables outside, sunset view. No dress code nonsense.', array['food', 'sunset', 'sea']::text[], 19, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunset%20at%20Agios%20Andreas.jpg?width=1200', 5),
  ('post-7', 'maria', 'katakolo-port', 'photo', '45 min ago', 'Katakolo is touristy but the port walk is actually nice at golden hour.', array['port', 'walk', 'photo']::text[], 27, 'https://commons.wikimedia.org/wiki/Special:FilePath/Katakolo%20Port.jpg?width=1200', 6),
  ('post-8', 'nikos', 'andritsaina', 'tip', 'tonight', 'Village night up here. Slow food, cold beers, better temperature than the coast.', array['village', 'beer', 'slow']::text[], 39, 'https://commons.wikimedia.org/wiki/Special:FilePath/Andritsaina%20overview.jpg?width=1200', 7)
