insert into public.routes (id, title, author_id, lede, duration, budget, tags, image_url, comment_count, saves_count, sort_order)
values
  ('route-1', 'Beach → Food → After', 'eleni', 'Do this if you want the obvious Kourouta night without wasting half the day.', '7h', '€€', array['party', 'beach', 'night']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Sunset%20in%20Kourouta%2C%20western%20Peloponnese%2C%20Greece.jpg?width=1200', 8, 30, 0),
  ('route-2', 'No-car Katakolo Day', 'nikos', 'Cruise off, walk the port, swim, eat by the sea. No rental needed.', '5h', '€', array['no car', 'cruise', 'walk']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Katakolo%20Port.jpg?width=1200', 11, 41, 1),
  ('route-3', 'Quiet South Coast', 'maria', 'Skip the crowds. Big sky, free beaches, sunset that ruins you for everywhere else.', '1 day', 'free', array['quiet', 'beach', 'sunset']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20of%20Kakovatos%2C%20Elis%2C%20Greece%20%281%29.jpg?width=1200', 14, 52, 2),
  ('route-4', 'Forest Escape', 'andreas', 'Trade the heat for shade. Oak trees, slow village, real mountain air.', 'half day', 'free', array['nature', 'shade', 'village']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Foloi%20Forest%20-%20panoramio.jpg?width=1200', 17, 63, 3),
  ('route-5', 'Ancient Without Boring', 'eleni', 'Culture, but the kind you actually want to talk about after.', '1 day', '€€', array['culture', 'roadtrip', 'views']::text[], 'https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20the%20archaeological%20site%20of%20Ancient%20Olympia%2C%20Greece%20%2851223832734%29.jpg?width=1200', 20, 74, 4)
insert into public.route_stops (route_id, position, display_time, place_id, title, body)
values
  ('route-1', 0, '17:30', 'kourouta-beach', 'Arrive late', 'Swim, chill, don''t roast in the midday heat.'),
  ('route-1', 1, '21:30', 'amaliada-square', 'Pregame in the square', 'Cheap food and pregame. More local than beach bar prices.'),
  ('route-1', 2, '23:45', 'kourouta-sunset', 'Back to Kourouta', 'Follow the music. Don''t overplan.'),
  ('route-2', 0, '10:00', 'katakolo-port', 'Port walk', 'Coffee, sea air, watch the cruise ships dock.'),
